// === Tab: tab2 ===
class Particle{

  x, y, ra, vm;
  d,f;

  let v = new PVector();

  constructor(){
    ra = random(1,3);
    x = random(ra,width-ra);
    y = random(ra,height-ra);
    d = int(random(10,100));
    let a = random(0,1);
    vm = random(1,5);
    if(a < 0.25){
      v.x = vm; v.y = 0;}
    else
    if(a < 0.5) {
      v.x = -vm; v.y = 0;}
    else
    if(a < 0.75) {
      v.x = 0; v.y = vm;}
    else {
      v.x = 0; v.y = -vm;}
    f = int(random(0,255));
  }

  function display(){
    fill(f);
    ellipse(x,y,2*ra,2*ra);
  }

  function move(){
    if(d > 0){
      x += v.x;
      y += v.y;
      d--;
    }
    else{
    var a = random(0,1);
    vm = random(1,5);
    if(a < 0.25){
      v.x = vm; v.y = 0;}
    else
    if(a < 0.5) {
      v.x = -vm; v.y = 0;}
    else
    if(a < 0.75) {
      v.x = 0; v.y = vm;}
    else {
      v.x = 0; v.y = -vm;}
    d = int(random(10,100));
    }   
  } 


  function check(){
  if ((x <= ra) || (x >= (width-ra))){
    v.x *= -1;
  }
  if ((y <= ra) || (y >= (height -ra))){
    v.y *= -1;
  }

  }

}

